"kind": "propose",
"summary": "The new revision's liveness and readiness probes are too strict, causing the app to be killed during startup. Adjusting probe timeouts should resolve this.",
"hypotheses": [
    {
        "root_cause_class": "probe_too_strict_for_startup",
        "summary": "The app takes longer to start than the liveness probe's timeout allows, leading to repeated failures.",
        "supporting": ["failure_onset_after_rollout", "killed_during_startup", "probe_kills"],
        "contradicting": ["oom_killed_new_revision", "crashed_on_its_own"],
        "missing": ["container_memory", "memory_at_limit_before_kill", "evicted_for_node_memory", "oom_after_long_run", "probe_timeouts"],
        "status": "supported"
    },
    {
        "root_cause_class": "new_version_broken",
        "summary": "The latest rollout introduced a version that fails, where the previous revision worked.",
        "supporting": ["failures_came_with_rollout", "earlier_revision_healthy"],
        "contradicting": ["config_changed_before_failure", "gitops_managed"],
        "missing": ["container_logs_tail", "image_pull_failure", "application_bug"],
        "status": "supported"
    },
    {
        "root_cause_class": "probe_timeout_too_short",
        "summary": "The liveness and readiness probes have timeoutSeconds set to 1, which is too short for the app to start.",
        "supporting": ["probe_kills", "probe_timeouts", "killed_during_startup"],
        "contradicting": ["application_bug", "node_problem"],
        "missing": ["container_memory", "memory_at_limit_before_kill", "evicted_for_node_memory", "oom_after_long_run"],
        "status": "supported"
    }
],
"proposal": {
    "capability": "deployment.set-probes",
    "target": {
        "group": "apps",
        "kind": "Deployment",
        "namespace": "edge",
        "name": "api-gateway",
        "uid": "uid-deployment-api-gateway"
    },
    "params": {
        "container": "app",
        "liveness": {
            "timeoutSeconds": 5
        },
        "readiness": {
            "timeoutSeconds": 5
        }
    },
    "expected_effect": "The liveness and readiness probes will have longer timeout periods, allowing the application to start before being terminated.",
    "rationale": "The evidence shows the app is killed during startup due to probe timeouts. Increasing the timeoutSeconds to 5 seconds should allow the application to start and pass the probes before being restarted.",
    "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
    "cited_predicates": ["failure_onset_after_rollout", "killed_during_startup", "probe_kills", "probe_timeouts"]
}
}
